typedef enum { KIND_EMPLOYEE, KIND_ENGINEER, KIND_MANAGER } Kind;

/* one row of the shared table */
typedef struct { long id; const char *name; Kind kind; const char *language; long reports; } EmployeeRow;

Employee *row_to_employee(const EmployeeRow *r) {
    switch (r->kind) {
    case KIND_ENGINEER: return engineer_new(r->id, r->name, r->language);
    case KIND_MANAGER:  return manager_new(r->id, r->name, r->reports);
    default:            return NULL;   /* unknown discriminator: mapping error */
    }
}
